mapper.select:
SELECT user_id, username, password, name, age, gender, email, phone_number, is_admin, is_manager, created_at
FROM users
WHERE username = #{username}

SELECT user_id, username, password, name, age, gender, email, phone_number, is_admin, is_manager, profile_img, created_at
FROM users
WHERE user_id = #{userId}

mapper.update:
UPDATE users
SET profile_img = #{profileImg, jdbcType=VARCHAR}
WHERE user_id = #{userId}

UPDATE users
SET is_manager = #{isManager}
WHERE user_id = #{userId}

